content:
if (full_fn)
                                        free(full_fn);

                                if (ret)
                                        break;

                                continue;
                        }

                        if (num_opts == alloc_opts) {
                                alloc_opts <<= 1;
                                opts = realloc(opts,
                                                alloc_opts * sizeof(char *));
                        }

                        opts[num_opts] = strdup(p);
                        num_opts++;
                }

                if (nested) {
                        *popts = opts;
                        *aopts = alloc_opts;
                        *nopts = num_opts;
                        goto out;
                }

                ret = fio_options_parse(td, opts, num_opts);

                if (!ret && td->o.read_iolog_file != NULL) {
                        char *fname = get_name_by_idx(td->o.read_iolog_file,
                                                      td->subjob_number);
                        if (!strcmp(fname, "-")) {
                                if (stdin_occupied) {
                                        log_err("fio: only one user (read_iolog_file/job "
                                                "file) of stdin is permitted at once but "
                                                "more than one was found.\n");
                                        ret = 1;
                                }
                                stdin_occupied = true;
                        }
                }
                if (!ret) {
                        if (dump_cmdline)
                                dump_opt_list(td);

                        ret = add_job(td, name, 0, 0, type);
                } else {
                        log_err("fio: job %s dropped\n", name);
                        put_job(td);
                }

                for (i = 0; i < num_opts; i++)
                        free(opts[i]);
                num_opts = 0;
        } while (!ret);

        if (dump_cmdline)
                log_info("\n");

        i = 0;
        while (i < nr_job_sections) {
                free(job_sections[i]);
                i++;
        }

        free(opts);
out:
        free(string);
        if (!nested)
                free(name);
        if (!is_buf && f != stdin)
                fclose(f);
        return ret;
}

int parse_jobs_ini(char *file, int is_buf, int stonewall_flag, int type)
{
        return __parse_jobs_ini(NULL, file, is_buf, stonewall_flag, type,
                        0, NULL, NULL, NULL, NULL);
}
